// @ts-check
// Every page of this site is generated by scripts/sync-kit-docs.mjs from the documents of ONE ai-second-opinion
// release, and the title and description below are read from that release's README (src/generated/kit.json).
// Nothing here restates a version, a model, a price or a count: the kit's documents do, for their own release.
import fs from 'node:fs';
import { defineConfig } from 'astro/config';
import starlight from '@astrojs/starlight';
import starlightLlmsTxt from 'starlight-llms-txt';

const kitFile = new URL('./src/generated/kit.json', import.meta.url);
if (!fs.existsSync(kitFile)) {
  throw new Error('src/generated/kit.json is missing - run `npm run sync -- --kit <ai-second-opinion checkout> --tag <vX.Y.Z>` first');
}
const KIT = JSON.parse(fs.readFileSync(kitFile, 'utf8'));

export default defineConfig({
  // The site lives at the domain root: no `base` (a base path sends every asset to a path that does not exist).
  site: 'https://secondai.net',
  // GitHub renders `--flag` and "quotes" as typed; smartypants would turn `--only` into an en dash in prose.
  markdown: { smartypants: false },
  integrations: [
    starlight({
      title: KIT.title,
      description: KIT.description,
      favicon: '/favicon.svg',
      defaultLocale: 'root',
      locales: {
        root: { label: 'English', lang: 'en' },
        ru: { label: 'Русский', lang: 'ru' },
      },
      social: [{ icon: 'github', label: 'GitHub', href: KIT.repo }],
      lastUpdated: false,
      plugins: [starlightLlmsTxt({ projectName: KIT.title, description: KIT.description })],
      // Labels are the pages' own titles, i.e. the first heading of each kit document.
      sidebar: ['index', 'install', 'technical', 'troubleshooting', 'privacy', 'security', 'contributing', 'changelog'],
    }),
  ],
});
